import{_ as r,C as t,o as a,c as l,a2 as o,b as s,w as i,a as c,E as d,a3 as u}from"./chunks/framework.CgxQ0r6v.js";const y=JSON.parse('{"title":"Manual de Estudio Profundo: Evaluación 1","description":"","frontmatter":{},"headers":[],"relativePath":"materias/Proyecto_Sociotecnologico_IV/documentacion/IV-XI/Lectura_Catedra_Evaluacion_1.md","filePath":"materias/Proyecto_Sociotecnologico_IV/documentacion/IV-XI/Lectura_Catedra_Evaluacion_1.md"}'),m={name:"materias/Proyecto_Sociotecnologico_IV/documentacion/IV-XI/Lectura_Catedra_Evaluacion_1.md"};function g(p,e,f,C,h,_){const n=t("Mermaid");return a(),l("div",null,[e[1]||(e[1]=o('<h1 id="manual-de-estudio-profundo-evaluacion-1" tabindex="-1">Manual de Estudio Profundo: Evaluación 1 <a class="header-anchor" href="#manual-de-estudio-profundo-evaluacion-1" aria-label="Permalink to &quot;Manual de Estudio Profundo: Evaluación 1&quot;">​</a></h1><h2 id="materia-proyecto-sociotecnologico-iv-trayecto-iv-trimestre-xi" tabindex="-1">Materia: Proyecto Sociotecnológico IV (Trayecto IV - Trimestre XI) <a class="header-anchor" href="#materia-proyecto-sociotecnologico-iv-trayecto-iv-trimestre-xi" aria-label="Permalink to &quot;Materia: Proyecto Sociotecnológico IV (Trayecto IV - Trimestre XI)&quot;">​</a></h2><h3 id="eje-tematico-gestion-profesional-de-proyectos-y-control-de-la-configuracion" tabindex="-1">Eje Temático: Gestión Profesional de Proyectos y Control de la Configuración <a class="header-anchor" href="#eje-tematico-gestion-profesional-de-proyectos-y-control-de-la-configuracion" aria-label="Permalink to &quot;Eje Temático: Gestión Profesional de Proyectos y Control de la Configuración&quot;">​</a></h3><hr><h2 id="🧭-introduccion-la-ingenieria-en-accion" tabindex="-1">🧭 Introducción: La Ingeniería en Acción <a class="header-anchor" href="#🧭-introduccion-la-ingenieria-en-accion" aria-label="Permalink to &quot;🧭 Introducción: La Ingeniería en Acción&quot;">​</a></h2><p>Al iniciar el <strong>Trimestre XI</strong>, el equipo de futuros ingenieros ingresa en la fase de construcción y materialización de la solución sociotecnológica aprobada.</p><p>En proyectos de envergadura institucional, el éxito no depende únicamente de la habilidad individual para escribir algoritmos, sino de la <strong>capacidad del equipo para coordinarse bajo metodologías ágiles o híbridas profesionales</strong>, controlar las versiones del software, gestionar los cambios en el alcance y mantener una disciplina rigurosa de control de la configuración.</p><hr><h2 id="⚙️-capitulo-i-gestion-agil-y-adaptativa-en-pst-iv" tabindex="-1">⚙️ CAPÍTULO I: Gestión Ágil y Adaptativa en PST IV <a class="header-anchor" href="#⚙️-capitulo-i-gestion-agil-y-adaptativa-en-pst-iv" aria-label="Permalink to &quot;⚙️ CAPÍTULO I: Gestión Ágil y Adaptativa en PST IV&quot;">​</a></h2>',9)),(a(),s(u,null,{default:i(()=>[d(n,{id:"mermaid-23",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20P%5B%22%F0%9F%93%8B%20Product%20Backlog%20(Historias%20de%20Usuario)%22%5D%20--%3E%20S%5B%22%F0%9F%8F%83%20Sprint%20Planning%20(Sprint%20de%202%20Semanas)%22%5D%0A%20%20%20%20S%20--%3E%20D%5B%22%F0%9F%92%BB%20Daily%20Standup%20(Sincronizaci%C3%B3n%20Diaria%2015%20min)%22%5D%0A%20%20%20%20D%20--%3E%20R%5B%22%F0%9F%94%8D%20Sprint%20Review%20%26%20Demo%20(Revisi%C3%B3n%20con%20Tutor%2FComunidad)%22%5D%0A%20%20%20%20R%20--%3E%20RET%5B%22%F0%9F%94%84%20Sprint%20Retrospective%20(Mejora%20Continua%20del%20Equipo)%22%5D%0A%20%20%20%20RET%20--%3E%20S%0A%0A%20%20%20%20style%20P%20fill%3A%231e293b%2Cstroke%3A%2364748b%2Ccolor%3A%23fff%0A%20%20%20%20style%20S%20fill%3A%230f766e%2Cstroke%3A%2314b8a6%2Ccolor%3A%23fff%0A%20%20%20%20style%20D%20fill%3A%230369a1%2Cstroke%3A%230ea5e9%2Ccolor%3A%23fff%0A%20%20%20%20style%20R%20fill%3A%231e3a8a%2Cstroke%3A%233b82f6%2Ccolor%3A%23fff%0A%20%20%20%20style%20RET%20fill%3A%234338ca%2Cstroke%3A%236366f1%2Ccolor%3A%23fff%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<h3 id="_1-1-gestion-del-alcance-y-control-de-cambios" tabindex="-1">1.1 Gestión del Alcance y Control de Cambios <a class="header-anchor" href="#_1-1-gestion-del-alcance-y-control-de-cambios" aria-label="Permalink to &quot;1.1 Gestión del Alcance y Control de Cambios&quot;">​</a></h3><p>En comunidades y organizaciones reales, los requerimientos evolucionan. Para evitar el desbordamiento del alcance (<em>Scope Creep</em>), se aplica el protocolo formal de cambio:</p><ol><li><strong>Solicitud de Cambio (RFC):</strong> El cliente o tutor propone una modificación.</li><li><strong>Análisis de Impacto:</strong> El equipo evalúa el impacto en tiempo, costo y complejidad.</li><li><strong>Decisión:</strong> Si el cambio es aceptado, se reemplaza una funcionalidad de igual esfuerzo en el backlog; si no, se difiere para una versión futura.</li></ol><hr><h2 id="🐙-capitulo-ii-gestion-de-la-configuracion-del-software-scm" tabindex="-1">🐙 CAPÍTULO II: Gestión de la Configuración del Software (SCM) <a class="header-anchor" href="#🐙-capitulo-ii-gestion-de-la-configuracion-del-software-scm" aria-label="Permalink to &quot;🐙 CAPÍTULO II: Gestión de la Configuración del Software (SCM)&quot;">​</a></h2><p>La <strong>Gestión de la Configuración</strong> garantiza la reproducibilidad exacta de cualquier versión del sistema en cualquier momento:</p><h3 id="_2-1-los-cuatro-pilares-del-scm" tabindex="-1">2.1 Los Cuatro Pilares del SCM <a class="header-anchor" href="#_2-1-los-cuatro-pilares-del-scm" aria-label="Permalink to &quot;2.1 Los Cuatro Pilares del SCM&quot;">​</a></h3><ol><li><strong>Identificación de la Configuración:</strong> Esquema formal de versionado semántico (<em>SemVer: MAJOR.MINOR.PATCH</em>).</li><li><strong>Control de Versiones y Ramas (GitFlow):</strong> Ramas protegidas (<code>main</code>, <code>develop</code>), ramas temporales (<code>feature/*</code>, <code>bugfix/*</code>) y fusiones mediante <em>Pull Requests</em> con revisión obligatoria por pares.</li><li><strong>Auditoría de la Configuración:</strong> Verificación de que cada commit esté asociado a un ticket o requerimiento de la matriz de trazabilidad.</li><li><strong>Gestión de Entornos (Ambientes de Desarrollo, Staging y Producción):</strong> Separación total de bases de datos y credenciales mediante archivos <code>.env</code> que jamás se suben al repositorio público.</li></ol><hr><h2 id="📝-conclusiones-y-entregables-de-la-evaluacion-1" tabindex="-1">📝 Conclusiones y Entregables de la Evaluación 1 <a class="header-anchor" href="#📝-conclusiones-y-entregables-de-la-evaluacion-1" aria-label="Permalink to &quot;📝 Conclusiones y Entregables de la Evaluación 1&quot;">​</a></h2><p>Para la Evaluación 1 del Trimestre XI:</p><ol><li><strong>Dossier de Gestión de Proyecto:</strong> Backlog de producto detallado con estimaciones en puntos de historia (Story Points).</li><li><strong>Plan de Control de la Configuración:</strong> Con políticas de ramas en Git, versionado y gestión de secretos/credenciales.</li><li><strong>Reporte del Sprint 1 Ejecutado:</strong> Evidencia de los primeros incrementos de software construidos.</li></ol>',12))])}const A=r(m,[["render",g]]);export{y as __pageData,A as default};
